import React, { useState } from "react";
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  Modal,
  StyleSheet,
} from "react-native";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

export default function App() {
  const [peso, setPeso] = useState("");
  const [altura, setAltura] = useState("");
  const [imc, setImc] = useState(null);
  const [classificacao, setClassificacao] = useState("");
  const [dica, setDica] = useState("");
  const [diferencaPeso, setDiferencaPeso] = useState("");
  const [modalVisible, setModalVisible] = useState(false);
  const [corClassificacao, setCorClassificacao] = useState("#4CAF50");

  const calcularDiferencaPeso = (pesoAtual, alturaMetros, imc) => {
    const pesoMin = 18.5 * alturaMetros * alturaMetros;
    const pesoMax = 24.9 * alturaMetros * alturaMetros;

    if (imc < 18.5) {
      const ganhar = pesoMin - pesoAtual;
      return { mensagem: `Você precisa ganhar pelo menos ${ganhar.toFixed(1)} kg.` };
    }

    if (imc > 24.9) {
      const perder = pesoAtual - pesoMax;
      return { mensagem: `Você precisa perder pelo menos ${perder.toFixed(1)} kg.` };
    }

    return { mensagem: "Você está no peso ideal!" };
  };

  const calcularIMC = () => {
    let pesoNum = parseFloat(peso.replace(",", "."));
    let alturaNum = parseFloat(altura.replace(",", "."));

    if (!peso || !altura) {
      toast.warn("Preencha todos os campos!");
      return;
    }
    if (isNaN(pesoNum) || isNaN(alturaNum)) {
      toast.error("Digite apenas números válidos!");
      return;
    }
    if (pesoNum <= 0) {
      toast.error("O peso precisa ser maior que zero!");
      return;
    }
    if (alturaNum <= 0) {
      toast.error("A altura precisa ser maior que zero!");
      return;
    }

    alturaNum = alturaNum / 100;

    const valorIMC = pesoNum / (alturaNum * alturaNum);
    const imcFormatado = valorIMC.toFixed(2);
    const { classificacao, dica, cor } = gerarClassificacaoEDica(valorIMC);

    const diff = calcularDiferencaPeso(pesoNum, alturaNum, valorIMC);

    setImc(imcFormatado);
    setClassificacao(classificacao);
    setDica(dica);
    setDiferencaPeso(diff.mensagem);
    setCorClassificacao(cor);
    setModalVisible(true);
  };

  const gerarClassificacaoEDica = (imc) => {
    if (imc < 18.5)
      return {
        classificacao: "Abaixo do peso",
        dica: "Procure incluir mais calorias e proteínas saudáveis na sua dieta.",
        cor: "#2196F3",
      };
    else if (imc < 24.9)
      return {
        classificacao: "Peso normal",
        dica: "Continue mantendo uma alimentação equilibrada!",
        cor: "#4CAF50",
      };
    else if (imc < 29.9)
      return {
        classificacao: "Sobrepeso",
        dica: "Inclua mais frutas e verduras e reduza ultraprocessados.",
        cor: "#FFC107",
      };
    else if (imc < 34.9)
      return {
        classificacao: "Obesidade grau I",
        dica:
          "Busque acompanhamento profissional para ajustar sua alimentação.",
        cor: "#FF9800",
      };
    else if (imc < 39.9)
      return {
        classificacao: "Obesidade grau II",
        dica: "É importante buscar ajuda médica.",
        cor: "#FF5722",
      };
    else
      return {
        classificacao: "Obesidade grau III",
        dica: "Procure orientação médica especializada.",
        cor: "#f44336",
      };
  };

  return (
    <View style={styles.container}>
      <ToastContainer position="top-center" autoClose={3000} />

      <Text style={styles.titulo}>HappyBody</Text>
      <Text style={styles.subtitulo}>Calculadora de IMC</Text>

      <TextInput
        style={styles.input}
        placeholder="Peso (kg)"
        keyboardType="numeric"
        value={peso}
        onChangeText={setPeso}
      />

      <TextInput
        style={styles.input}
        placeholder="Altura (cm)"
        keyboardType="numeric"
        value={altura}
        onChangeText={setAltura}
      />

      <TouchableOpacity style={styles.botao} onPress={calcularIMC}>
        <Text style={styles.textoBotao}>Calcular</Text>
      </TouchableOpacity>

      <Modal visible={modalVisible} animationType="slide" transparent>
        <View style={styles.modalFundo}>
          <View style={styles.modalConteudo}>
            <Text style={styles.resultado}>Seu IMC é {imc}</Text>

            <Text style={[styles.classificacao, { color: corClassificacao }]}>
              {classificacao}
            </Text>

            <Text style={styles.diferenca}>{diferencaPeso}</Text>

            <Text style={styles.dica}>{dica}</Text>

            {/* Tabela */}
            <View style={styles.tabela}>
              {[
                { faixa: "Menor que 18.5", nome: "Abaixo do peso" },
                { faixa: "18.5 - 24.9", nome: "Peso normal" },
                { faixa: "25 - 29.9", nome: "Sobrepeso" },
                { faixa: "30 - 34.9", nome: "Obesidade grau I" },
                { faixa: "35 - 39.9", nome: "Obesidade grau II" },
                { faixa: "40 ou mais", nome: "Obesidade grau III" },
              ].map((item, i) => (
                <View
                  key={i}
                  style={[
                    styles.linhaTabela,
                    item.nome === classificacao && styles.destacarLinha,
                  ]}
                >
                  <Text style={styles.textoTabela}>{item.faixa}</Text>
                  <Text style={styles.textoTabela}>{item.nome}</Text>
                </View>
              ))}
            </View>

            <TouchableOpacity
              style={styles.fecharBotao}
              onPress={() => setModalVisible(false)}
            >
              <Text style={styles.textoFechar}>Fechar</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>
    </View>
  );
}

const styles = StyleSheet.create({
  diferenca: {
    fontSize: 16,
    fontWeight: "bold",
    marginBottom: 15,
    color: "#222",
    textAlign: "center",
  },
  tabela: {
    width: "100%",
    marginTop: 10,
    borderWidth: 1,
    borderColor: "#ccc",
    borderRadius: 10,
  },
  linhaTabela: {
    flexDirection: "row",
    justifyContent: "space-between",
    padding: 10,
  },
  destacarLinha: {
    backgroundColor: "#ffd4d4",
  },
  textoTabela: {
    fontSize: 14,
    color: "#333",
  },
  // (mantém seus estilos anteriores)
});
